// Generated by vibelang from src/home/sessions/archive.ts; the migrate flow writes it again with each batch.
import { notifySessionTabsRemoved } from "@/shell/titlebar/session-events";
export async function archiveHomeSession(input) {
    await input
        .archive(input.session.id)
        .then(() => {
        input.remove();
        notifySessionTabsRemoved({
            server: input.server,
            directory: input.session.location.directory,
            sessionIDs: [input.session.id],
        });
    })
        .catch((error) => input.onError?.(error));
}
